/* Actual syllabus algorithms, independent of the interface. */
const Algorithms = (() => {
function validate(jobs,W){if(!Number.isInteger(W)||W<0||W>5000)throw Error('Budget must be a whole number from 0 to 5,000.');if(jobs.length>100)throw Error('Use at most 100 tasks.');const names=new Set();for(const j of jobs){if(!j.name.trim()||names.has(j.name))throw Error('Give each task a different name.');names.add(j.name);if(!Number.isInteger(j.cost)||j.cost<1||j.cost>5000||!Number.isInteger(j.benefit)||j.benefit<0||j.benefit>100000||!Number.isInteger(j.priority)||j.priority<1||j.priority>1000)throw Error('Cost: 1–5,000. Benefit: 0–100,000. Priority: 1–1,000. Use whole numbers.');}}
function knapsack(jobs,W,partial=false){validate(jobs,W);let chosen=[],steps=0;if(partial){let remaining=W;for(const j of [...jobs].sort((a,b)=>b.benefit/b.cost-a.benefit/a.cost)){if(remaining<=0)break;const share=Math.min(1,remaining/j.cost);chosen.push({...j,share});remaining-=j.cost*share;steps++;}}else{const dp=Array.from({length:jobs.length+1},()=>new Float64Array(W+1));for(let i=1;i<=jobs.length;i++)for(let w=0;w<=W;w++){const j=jobs[i-1];dp[i][w]=dp[i-1][w];if(j.cost<=w)dp[i][w]=Math.max(dp[i][w],dp[i-1][w-j.cost]+j.benefit);steps++;}let w=W;for(let i=jobs.length;i>0;i--)if(dp[i][w]!==dp[i-1][w]){chosen.push({...jobs[i-1],share:1});w-=jobs[i-1].cost;}chosen.reverse();}return {chosen,cost:chosen.reduce((s,j)=>s+j.cost*j.share,0),benefit:chosen.reduce((s,j)=>s+j.benefit*j.share,0),steps,algorithm:partial?'Fractional Knapsack':'0/1 Knapsack'};}
function matrix(d){if(d.length<2||d.length>31||d.some(x=>!Number.isInteger(x)||x<1||x>10000))throw Error('Use 2–31 dimensions, each a whole number from 1 to 10,000.');const n=d.length-1,dp=Array.from({length:n},()=>Array(n).fill(0)),split=Array.from({length:n},()=>Array(n).fill(0));let steps=0;for(let len=2;len<=n;len++)for(let i=0;i+len<=n;i++){const j=i+len-1;dp[i][j]=Infinity;for(let k=i;k<j;k++){steps++;const cost=dp[i][k]+dp[k+1][j]+d[i]*d[k+1]*d[j+1];if(cost<dp[i][j]){dp[i][j]=cost;split[i][j]=k;}}}const group=(i,j)=>i===j?'A'+(i+1):`(${group(i,split[i][j])} × ${group(split[i][j]+1,j)})`;let baseline=0;for(let k=1;k<n;k++)baseline+=d[0]*d[k]*d[k+1];return {baseline,optimal:dp[0][n-1],order:group(0,n-1),steps};}
class BinomialHeap{
constructor(){this.roots=[];this.handles=new Map();this.links=0;this.cuts=0;this.swaps=0;}
consolidate(){const degrees=new Map();for(let node of this.roots){while(degrees.has(node.children.length)){let other=degrees.get(node.children.length);degrees.delete(node.children.length);if(other.key<node.key)[node,other]=[other,node];other.parent=node;node.children.push(other);this.links++;}degrees.set(node.children.length,node);}this.roots=[...degrees.values()];}
insert(key,item){if(this.handles.has(item))throw Error('Duplicate task');const n={key,item,parent:null,children:[]};this.handles.set(item,n);this.roots.push(n);this.consolidate();}
decrease(item,key){let n=this.handles.get(item);if(!n||key>n.key)throw Error('Priority must decrease.');n.key=key;while(n.parent&&n.key<n.parent.key){const p=n.parent;[n.key,p.key]=[p.key,n.key];[n.item,p.item]=[p.item,n.item];this.handles.set(n.item,n);this.handles.set(p.item,p);n=p;this.swaps++;}}
extract(){if(!this.roots.length)return null;let n=this.roots.reduce((a,b)=>a.key<=b.key?a:b);this.roots.splice(this.roots.indexOf(n),1);for(const c of n.children)c.parent=null;this.roots.push(...n.children);this.handles.delete(n.item);this.consolidate();return {key:n.key,item:n.item};}}
class FibonacciHeap{
constructor(){this.min=null;this.handles=new Map();this.links=0;this.cuts=0;this.swaps=0;}
ring(start){if(!start)return [];let out=[start],n=start.right;while(n!==start){out.push(n);n=n.right;}return out;}
detach(n){n.left.right=n.right;n.right.left=n.left;n.left=n.right=n;}
after(a,n){n.left=a;n.right=a.right;a.right.left=n;a.right=n;}
root(n){n.parent=null;n.mark=false;if(!this.min)this.min=n;else{this.after(this.min,n);if(n.key<this.min.key)this.min=n;}}
insert(key,item){if(this.handles.has(item))throw Error('Duplicate task');const n={key,item,parent:null,child:null,degree:0,mark:false};n.left=n.right=n;this.handles.set(item,n);this.root(n);}
link(c,p){c.parent=p;c.mark=false;if(!p.child)p.child=c;else this.after(p.child,c);p.degree++;this.links++;}
consolidate(){const roots=this.ring(this.min),degrees=new Map();for(const n of roots)n.left=n.right=n;for(let n of roots){while(degrees.has(n.degree)){let o=degrees.get(n.degree);degrees.delete(n.degree);if(o.key<n.key)[n,o]=[o,n];this.link(o,n);}degrees.set(n.degree,n);}this.min=null;for(const n of degrees.values())this.root(n);}
extract(){const z=this.min;if(!z)return null;for(const c of this.ring(z.child)){this.detach(c);this.root(c);}const next=z.right;this.detach(z);this.handles.delete(z.item);this.min=next===z?null:next;if(this.min)this.consolidate();return {key:z.key,item:z.item};}
cut(n,p){if(p.child===n)p.child=n.right===n?null:n.right;this.detach(n);p.degree--;this.root(n);this.cuts++;}
decrease(item,key){const n=this.handles.get(item);if(!n||key>n.key)throw Error('Priority must decrease.');n.key=key;let p=n.parent;if(p&&n.key<p.key){this.cut(n,p);while(p.parent){const g=p.parent;if(!p.mark){p.mark=true;break;}this.cut(p,g);p=g;}}if(n.key<this.min.key)this.min=n;}}
class BTree{
constructor(){this.t=3;this.root={keys:[],values:[],children:[],leaf:true};}
search(key){let n=this.root;while(true){let i=0;while(i<n.keys.length&&key>n.keys[i])i++;if(n.keys[i]===key)return n.values[i];if(n.leaf)return null;n=n.children[i];}}
split(p,i){const c=p.children[i],t=this.t,o={leaf:c.leaf,keys:c.keys.slice(t),values:c.values.slice(t),children:c.leaf?[]:c.children.slice(t)};p.keys.splice(i,0,c.keys[t-1]);p.values.splice(i,0,c.values[t-1]);c.keys=c.keys.slice(0,t-1);c.values=c.values.slice(0,t-1);if(!c.leaf)c.children=c.children.slice(0,t);p.children.splice(i+1,0,o);}
insert(key,value){let n=this.root;while(true){let i=0;while(i<n.keys.length&&key>n.keys[i])i++;if(n.keys[i]===key){n.values[i]=value;return;}if(n.leaf)break;n=n.children[i];}if(this.root.keys.length===5){this.root={keys:[],values:[],children:[this.root],leaf:false};this.split(this.root,0);}n=this.root;while(true){let i=0;while(i<n.keys.length&&key>n.keys[i])i++;if(n.leaf){n.keys.splice(i,0,key);n.values.splice(i,0,value);return;}if(n.children[i].keys.length===5){this.split(n,i);if(key>n.keys[i])i++;}n=n.children[i];}}}
function priorities(jobs,urgent){const results=[];for(const Heap of [BinomialHeap,FibonacciHeap]){const h=new Heap(),start=performance.now();for(const j of jobs)h.insert(j.priority,j.name);const first=h.extract(),order=first?[first]:[];const updated=!!urgent&&h.handles.has(urgent);if(updated)h.decrease(urgent,0);while(h.handles.size)order.push(h.extract());results.push({name:Heap.name,order,updated,ms:performance.now()-start,links:h.links,cuts:h.cuts,swaps:h.swaps});}return results;}
return {validate,knapsack,matrix,BinomialHeap,FibonacciHeap,BTree,priorities};})();
if(typeof module!=='undefined')module.exports=Algorithms;
